#!/usr/bin/env python3
"""Scan all jsonl session files for owner (user, string-content) messages matching
intake-chain keywords. Skip judge/audit files via cheap first-5-line filter.
Print: file basename, line number, timestamp, clipped text.
"""
import json, sys, os, re

DIR = "/Users/sashaabramovich/.claude/projects/-Users-sashaabramovich/"
KEYWORDS = re.compile(
    r"матриц|сквозн|локальн\w*\s+фич|локальн\w*\s+измен|фич[аеуы]|feature|traceability|"
    r"архитектур|TEST_MATRIX|ARCHITECTURE\.md|какие тест|классиф|интейк|intake|запрос.*фич|"
    r"новый.*правк|правк.*нов|раздел.*подфункц|подфункционал",
    re.IGNORECASE,
)
JUDGE_MARK = re.compile(r'"register judge"|"queue-operation"|"enqueue"')

def clip(s, n=400):
    s = " ".join(s.split())
    return s if len(s) <= n else s[:n] + " …[cut]"

files = sorted(f for f in os.listdir(DIR) if f.endswith(".jsonl"))
print(f"Total files: {len(files)}", file=sys.stderr)

for fname in files:
    path = os.path.join(DIR, fname)
    try:
        with open(path, errors="replace") as fh:
            head_lines = [fh.readline() for _ in range(5)]
    except Exception:
        continue
    head_text = "".join(head_lines)
    if JUDGE_MARK.search(head_text):
        continue
    # now scan full file for user string-content messages
    try:
        with open(path, errors="replace") as fh:
            for lineno, line in enumerate(fh, 1):
                line = line.strip()
                if not line or '"role":"user"' not in line and '"role": "user"' not in line:
                    continue
                try:
                    j = json.loads(line)
                except Exception:
                    continue
                if j.get("type") != "user":
                    continue
                m = j.get("message") or {}
                c = m.get("content")
                if not isinstance(c, str):
                    continue
                if "<task-notification>" in c or "<local-command-caveat>" in c or "Stop hook feedback" in c or c.startswith("<command-name>"):
                    continue
                if KEYWORDS.search(c):
                    ts = (j.get("timestamp") or "")[:16]
                    print(f"{fname}\t{lineno}\t{ts}\t{clip(c)}")
    except Exception as e:
        print(f"ERR {fname}: {e}", file=sys.stderr)

